import { useState, useEffect } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";

export default function EditarUsuario() {
  const { id } = useParams();
  const [formData, setFormData] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    foto: null,
  });

  useEffect(() => {
    axios.get(`http://localhost:3001/usuarios/${id}`).then((res) => {
      setFormData(res.data);
    });
  }, [id]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    setFormData({ ...formData, foto: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    data.append("nome", formData.nome);
    data.append("idade", formData.idade);
    data.append("rua", formData.rua);
    data.append("bairro", formData.bairro);
    data.append("estado", formData.estado);
    data.append("biografia", formData.biografia);
    if (formData.foto) data.append("foto", formData.foto);

    try {
      await axios.put(`http://localhost:3001/usuarios/${id}`, data);
      alert("Usuário atualizado com sucesso!");
    } catch (error) {
      console.error("Erro ao atualizar usuário:", error);
      alert("Erro ao atualizar usuário.");
    }
  };

  return (
    <div className="container mt-5">
      <h2 className="mb-4 text-center">Editar Usuário</h2>
      <form onSubmit={handleSubmit} className="row g-3" encType="multipart/form-data">
        <div className="col-md-6">
          <input
            type="text"
            name="nome"
            className="form-control"
            placeholder="Nome completo"
            value={formData.nome}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="number"
            name="idade"
            className="form-control"
            placeholder="Idade"
            value={formData.idade}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="text"
            name="rua"
            className="form-control"
            placeholder="Rua"
            value={formData.rua}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="text"
            name="bairro"
            className="form-control"
            placeholder="Bairro"
            value={formData.bairro}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="text"
            name="estado"
            className="form-control"
            placeholder="Estado"
            value={formData.estado}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-12">
          <textarea
            name="biografia"
            className="form-control"
            placeholder="Biografia"
            rows="3"
            value={formData.biografia}
            onChange={handleChange}
          />
        </div>
        <div className="col-12">
          <input
            type="file"
            name="foto"
            className="form-control"
            accept="image/*"
            onChange={handleFileChange}
          />
        </div>
        <div className="col-12 text-center">
          <button type="submit" className="btn btn-primary mt-3">
            Salvar Alterações
          </button>
        </div>
      </form>
    </div>
  );
}
